// Monta a lista de quem está online como HTML, no BACKEND (Bun + jsdom).
// ctx.getPlayers() = jogadores de todos os shards deste servidor, como o mod reporta.
// O ui_builder recebe o HTML pronto pelo campo "HTML em runtime" ({{s.html}}).
async function run(ctx) {
  const players = ctx.getPlayers()
  const doc = await ctx.dom(
    '<panel title="Online" width="380" gap="6">' +
    '  <text id="total" size="16" color="0.8,0.8,0.8,1"></text>' +
    '  <div id="lista" style="overflow:scroll; height:220; gap:4; width:340"></div>' +
    '  <button callback="close" width="140" height="40">Fechar</button>' +
    '</panel>')
  doc.querySelector('#total').textContent = players.length + ' jogador(es) online'
  const lista = doc.querySelector('#lista')
  for (const p of players) {
    const row = doc.createElement('div')
    row.setAttribute('style', 'display:flex; flex-direction:row; gap:8; align-items:center')
    const icon = doc.createElement('icon')
    icon.setAttribute('prefab', p.prefab || 'wilson'); icon.setAttribute('size', '28')
    const name = doc.createElement('text')
    name.setAttribute('size', '16'); name.setAttribute('width', '170')
    name.textContent = (p.admin ? '[ADM] ' : '') + (p.name || p.userid)
    const hp = doc.createElement('bar')
    hp.setAttribute('value', String(p.health ? p.health.current : 0))
    hp.setAttribute('max', String(p.health ? p.health.max : 1))
    hp.setAttribute('width', '90'); hp.setAttribute('height', '12'); hp.setAttribute('color', '0.2,0.8,0.2,1')
    row.append(icon, name, hp)
    lista.appendChild(row)
  }
  return { html: ctx.html(doc), count: players.length }
}
